compile.workshop:
settings
{
	lobby
	{
		Max FFA Players: 6
	}
	modes
	{
		Deathmatch
		{
			enabled maps
			{
				King's Row Winter
			}
		}
		General
		{
			Allow Hero Switching: Off
			Hero Limit: Off
			Respawn As Random Hero: On
			Respawn Time Scalar: 30%
		}
	}
	heroes
	{
		General
		{
			Mei
			{
				Primary Fire: Off
				Secondary Fire: Off
				Cryo-Freeze: Off
				Health: 266.4%
				Ice Wall: Off
				Ultimate Generation - Passive Blizzard: 0%
				Ultimate Generation - Combat Blizzard: 0%
			}
			enabled heroes
			{
				Mei
			}
		}
	}
}

variables {
    global:
        0: i
        1: rectangleChimneys
        2: rectangleChimneysAB
        3: rectangleChimneysAD
        4: rectangleChimneysABDot
        5: rectangleChimneysADDot
        6: rectangleChimneysSpheres
        7: sphereChimneys
        8: factoryChimneys
        9: chimneys
        10: gameStarted
        11: finisher
        12: antiCrashActivated
    player:
        0: pos
        1: i
        2: gottenChimneys
        3: reindeer
        4: score
        5: nbChimneysGotten
}

subroutines {
    0: gotChimney
}

