rule ("Initialize player variables") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Player Variable(Event Player, pos, Vector(-17.4, 39.19, -91.84));
    }
}

rule ("init AB AD") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(i, 0, Count Of(Global.rectangleChimneys), 1);
            Modify Global Variable(rectangleChimneysAB, Append To Array, Vector Towards(Multiply(Value In Array(Global.rectangleChimneys, Multiply(Global.i, 4)), Vector(1, 0, 1)), Multiply(Value In Array(Global.rectangleChimneys, Add(Multiply(Global.i, 4), 1)), Vector(1, 0, 1))));
            Modify Global Variable(rectangleChimneysAD, Append To Array, Vector Towards(Multiply(Value In Array(Global.rectangleChimneys, Multiply(Global.i, 4)), Vector(1, 0, 1)), Multiply(Value In Array(Global.rectangleChimneys, Add(Multiply(Global.i, 4), 3)), Vector(1, 0, 1))));
            Modify Global Variable(rectangleChimneysABDot, Append To Array, Dot Product(Vector Towards(Multiply(Value In Array(Global.rectangleChimneys, Multiply(Global.i, 4)), Vector(1, 0, 1)), Multiply(Value In Array(Global.rectangleChimneys, Add(Multiply(Global.i, 4), 1)), Vector(1, 0, 1))), Vector Towards(Multiply(Value In Array(Global.rectangleChimneys, Multiply(Global.i, 4)), Vector(1, 0, 1)), Multiply(Value In Array(Global.rectangleChimneys, Add(Multiply(Global.i, 4), 1)), Vector(1, 0, 1)))));
            Modify Global Variable(rectangleChimneysADDot, Append To Array, Dot Product(Vector Towards(Multiply(Value In Array(Global.rectangleChimneys, Multiply(Global.i, 4)), Vector(1, 0, 1)), Multiply(Value In Array(Global.rectangleChimneys, Add(Multiply(Global.i, 4), 3)), Vector(1, 0, 1))), Vector Towards(Multiply(Value In Array(Global.rectangleChimneys, Multiply(Global.i, 4)), Vector(1, 0, 1)), Multiply(Value In Array(Global.rectangleChimneys, Add(Multiply(Global.i, 4), 3)), Vector(1, 0, 1)))));
        End;
    }
}

rule ("game instructions") {
    event {
        Ongoing - Global;
    }
    conditions {
        Is In Setup == True;
    }
    actions {
        Set Match Time(999);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String(" \n\n\n\n"), Right, 1, Null, Null, Color(White), Visible To, Default Visibility);
        Create HUD Text(All Players(All Teams), Custom String(" \n\n\n\n\n\n\n\n                                           \n\n\n\n\n\n\n\n\n\n\n\n\n"), Custom String("                          "), Null, Right, 2, Color(Turquoise), Color(White), Color(White), Visible To, Default Visibility);
        Wait(5, Ignore Condition);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String(" \n\n\n"), Top, 1, Null, Null, Color(Sky Blue), Visible To and String, Visible Always);
        Create HUD Text(All Players(All Teams), Custom String("{0} santa's satan?! {0}", Ability Icon String(Hero(Mei), Button(Ultimate))), Null, Null, Top, 2, Color(Sky Blue), Null, Null, Visible To and String, Visible Always);
        Wait(5, Ignore Condition);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String(" \n"), Top, 3, Null, Null, Color(Sky Blue), Visible To and String, Visible Always);
        Create HUD Text(All Players(All Teams), Custom String("it's christmas, and it's time to deliver the gifts..."), Null, Null, Top, 4, Color(Blue), Null, Null, Visible To and String, Visible Always);
        Wait(5, Ignore Condition);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String(" \n"), Top, 5, Null, Null, Color(Sky Blue), Visible To and String, Visible Always);
        Create HUD Text(All Players(All Teams), Custom String("throw snowball ({0}) in each chimney to win!", Input Binding String(Button(Ultimate))), Null, Null, Top, 6, Color(Red), Null, Null, Visible To and String, Visible Always);
        Wait(5, Ignore Condition);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String(" \n"), Top, 7, Null, Null, Color(Sky Blue), Visible To and String, Visible Always);
        Create HUD Text(All Players(All Teams), Custom String("but it seems your reindeer is not so cooperative..."), Null, Null, Top, 8, Color(Green), Null, Null, Visible To and String, Visible Always);
        Wait(7, Ignore Condition);
        Create HUD Text(All Players(All Teams), Null, Null, Custom String(" \n"), Top, 9, Null, Null, Color(Sky Blue), Visible To and String, Visible Always);
        Create HUD Text(All Players(All Teams), Custom String("turn with mouse, {0} to go up, {1} to go down", Input Binding String(Button(Jump)), Input Binding String(Button(Crouch))), Null, Null, Top, 10, Color(Yellow), Null, Null, Visible To and String, Visible Always);
        Wait(8, Ignore Condition);
        Set Match Time(5);
    }
}

rule ("game started") {
    event {
        Ongoing - Global;
    }
    conditions {
        Is Game In Progress == True;
    }
    actions {
        Destroy All HUD Text;
        Set Global Variable(gameStarted, True);
        Disable Built-In Game Mode Completion;
        Disable Built-In Game Mode Scoring;
        Disable Inspector Recording;
        Big Message(All Players(All Teams), Custom String("go!"));
        Wait(0.016, Ignore Condition);
        Create HUD Text(All Players(All Teams), Null, Custom String("load: {0} | avg: {1} | peak: {2}", Server Load, Server Load Average, Server Load Peak), Null, Left, 1, Null, Color(White), Null, Visible To and String, Default Visibility);
    }
}

rule ("init player") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is Dummy Bot(Event Player) == False;
        Has Spawned(Event Player) == True;
    }
    actions {
        Set Player Variable At Index(Event Player, gottenChimneys, Subtract(Count Of(Global.chimneys), 1), 0);
        Disallow Button(Event Player, Button(Ultimate));
        Wait(0.1, Ignore Condition);
        Start Facing(Event Player, Vector(-0.18, 0, 0.98), 999, To World, Direction and Turn Rate);
        Start Forcing Player Position(Event Player, (Event Player).pos, True);
        Set Status(Event Player, Null, Phased Out, 9999);
        Disable Kill Feed(Event Player);
        "left"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(1, 0, -2), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(1, 0, 3), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "right"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(-1, 0, -2), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(-1, 0, 3), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "front"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(1, 0, 3), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(-1, 0, 3), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "back"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(1, 0, -2), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(-1, 0, -2), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "back point left"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(1, 0, -2), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(0, 2, -3), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "back point right"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(-1, 0, -2), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(0, 2, -3), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "front point left"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(1, 0, 3), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(0, 1.5, 2), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "front point right"
        Create Beam Effect(All Players(All Teams), Grapple Beam, Update Every Frame(World Vector Of(Vector(-1, 0, 3), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(0, 1.5, 2), Event Player, Rotation And Translation)), Null, Visible To Position and Radius);
        "beam to orisa"
        Create Beam Effect(All Players(All Teams), Bad Beam, Update Every Frame(World Vector Of(Vector(0, 1.5, 2), Event Player, Rotation And Translation)), Update Every Frame(World Vector Of(Vector(0, 1.5, 6), Event Player, Rotation And Translation)), Color(Red), Visible To Position and Radius);
        "orisa"
        Create Dummy Bot(Hero(Orisa), All Teams, Add(Slot Of(Event Player), 6), Null, Null);
        Set Player Variable(Event Player, reindeer, Last Created Entity);
        Start Forcing Player Position((Event Player).reindeer, World Vector Of(Vector(0, -0.5, 5.5), Event Player, Rotation And Translation), True);
        Attach Players((Event Player).reindeer, Event Player, Vector(0, -0.5, 5.5));
        Start Facing((Event Player).reindeer, Multiply(Facing Direction Of(Event Player), Vector(1, 0, 1)), 999, To World, Direction and Turn Rate);
        Set Status((Event Player).reindeer, Null, Phased Out, 9999);
        Disable Movement Collision With Environment((Event Player).reindeer, True);
    }
}

rule ("game started, players can move") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Global.gameStarted != False;
    }
    actions {
        Chase Player Variable At Rate(Event Player, pos, Add((Event Player).pos, Multiply(Multiply(Facing Direction Of(Event Player), Vector(1, 0, 1)), 99)), 15, Destination and Rate);
        Chase Player Variable At Rate(Event Player, score, 9999, 0.001, Destination and Rate);
        Stop Facing(Event Player);
    }
}

rule ("set ult") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Global.gameStarted != False;
        Ultimate Charge Percent(Event Player) < 100;
    }
    actions {
        Set Ultimate Charge(Event Player, Add(Ultimate Charge Percent(Event Player), 1));
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

