rule ("go up") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Global.gameStarted != False;
        Is Button Held(Event Player, Button(Jump)) == True;
        Y Component Of(Position Of(Event Player)) < 150;
    }
    actions {
        Modify Player Variable(Event Player, pos, Add, Vector(0, 0.1, 0));
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("go down") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Global.gameStarted != False;
        Is Button Held(Event Player, Button(Crouch)) == True;
        Y Component Of(Position Of(Event Player)) > 15;
    }
    actions {
        Modify Player Variable(Event Player, pos, Add, Vector(0, -0.1, 0));
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("player found all chimneys") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Global.finisher == Null;
        (Event Player).nbChimneysGotten >= 71;
    }
    actions {
        Big Message(All Players(All Teams), Custom String("{0} delivered to all chimneys!", Event Player));
        Set Global Variable(finisher, Event Player);
        Wait(3, Ignore Condition);
        Big Message(All Players(All Teams), Custom String("Game ends in 30 seconds"));
        Set Match Time(30);
    }
}

rule ("game ended") {
    event {
        Ongoing - Global;
    }
    conditions {
        Match Time == 0;
        Is Game In Progress == True;
    }
    actions {
        Declare Player Victory(Last Of(Sorted Array(All Players(All Teams), (Current Array Element).score)));
    }
}

rule ("anti crash") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.antiCrashActivated == False;
        Server Load > 250;
    }
    actions {
        Wait(1, Abort When False);
        Small Message(All Players(All Teams), Custom String("anti-crash system activated"));
        Set Slow Motion(10);
        Set Global Variable(antiCrashActivated, True);
    }
}

rule ("disable anti crash") {
    event {
        Ongoing - Global;
    }
    conditions {
        Global.antiCrashActivated != False;
        Server Load < 230;
    }
    actions {
        Set Slow Motion(100);
        Set Global Variable(antiCrashActivated, False);
    }
}
